import{_ as a}from"./chunks/5c8384462351c46b7dee.DxqEvQls.js";import{_ as r,C as o,o as n,c as s,j as e,a as i,E as l,a5 as h}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"分心是21世纪最大的陷阱","description":"","frontmatter":{"title":"分心是21世纪最大的陷阱","originalTitle":"Distraction Is The Greatest Trap Of The 21st Century","date":"2023-01-07","originalUrl":"https://thedankoe.com/letters/distraction-is-the-greatest-trap-of-the-21st-century/","minutes":16,"sourceHash":"fd0f80f24f0abfdc13fc85dbf6b0ddbea7fb0188857b0646ca1d0cd7073f2900","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/distraction-is-the-greatest-trap-of-the-21st-century/"}]]},"headers":[],"relativePath":"letters/distraction-is-the-greatest-trap-of-the-21st-century.md","filePath":"letters/distraction-is-the-greatest-trap-of-the-21st-century.md"}'),c={name:"letters/distraction-is-the-greatest-trap-of-the-21st-century.md"};function d(m,p,f,g,u,b){const t=o("ArticleMeta");return n(),s("div",null,[p[0]||(p[0]=e("h1",{id:"分心是21世纪最大的陷阱",tabindex:"-1"},[i("分心是21世纪最大的陷阱 "),e("a",{class:"header-anchor",href:"#分心是21世纪最大的陷阱","aria-label":'Permalink to "分心是21世纪最大的陷阱"'},"​")],-1)),l(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/f29w0p8enbw?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>中世纪，也被称为“黑暗时代”，是一个充满战争、无知、饥荒和流行病的时代。</p><p>随之而来的是为现代文明奠定基础的时代——文艺复兴时期。这是一次文化、政治和经济的重生，孕育了许多我们今天熟知的思想家、艺术家和科学家。</p><p>历史在重演，数字黑暗时代已经降临到我们身边。</p><p>但是，地平线上出现了一丝曙光。</p><p>数字黑暗时代是一个充斥着分心、思想封闭和廉价多巴胺的时代。</p><p>我们已经与那些曾赋予个人未来确定感的信仰体系失去了联系。</p><p>而且，如果我们不亲自去创造自己的使命感，我们就会用分心来维持仅存的一点理智。</p><p>拥有一个愿景——一个由你创造的愿景——能让你对生活产生掌控感。这是一个能为你当下的行动注入动力的使命。</p><p>这个愿景呈现出一个目标层级，随着你掌握实现这些目标所需的技能，其挑战性也会不断增加。</p><p>这就是你创造源源不断的优质多巴胺的方式。</p><p>一个有意识地自我创造出来的愿景，会迫使你集中注意力。</p><p>专注的大脑是享受生活的源泉。</p><p>如果没有愿景，<a href="https://thedankoe.com/the-focus-formula-how-to-take-control-of-your-life/" target="_blank" rel="noreferrer">你不可避免地会成为系统的奴隶。</a></p><p>你会逃避思考自己的未来，因为它看起来痛苦、绝望且充满不确定性。</p><p>正因如此，你会在以下几件事中寻找慰藉：</p><p><strong>1) 社会机器</strong></p><p>上学、找工作、快乐退休，这条清晰的路径很诱人。于是，你放弃了选择的自由，乖乖照做。</p><p><strong>2) 暂时的享乐</strong></p><p>在内心深处，我们知道自己没有做出正确的选择。</p><p>那是令人痛苦的。</p><p>所以我们用无休止地刷手机、狂看情景喜剧，以及那些只有几秒钟好口感却会降低我们巅峰运转能力的食物来麻痹自己的大脑——既然你的未来已经被决定了，为什么还需要保持巅峰状态呢？</p><p><strong>3) 现代的分心物</strong></p><p>分心不仅仅是数字化的。</p><p>它们是所有与你愿景不一致的事物。</p><p>如果你没有愿景，你又该如何从毫无意义的事物中筛选出重要的东西呢？</p><p>这些分心物的催化剂是<em>你</em>。你的身份认同。</p><p>别人告诉你该学什么、想什么、做什么。</p><p>你没有质疑，而是把它当作事实接受了。</p><p>所以，你的思维被局限在所有能强化这种身份认同的事物上，并对任何与此不符的事物感到威胁。</p><p>这三点可以归结为一件事，即21世纪最大的陷阱：</p><p>思想封闭。</p><h2 id="思想封闭的迹象" tabindex="-1">思想封闭的迹象 <a class="header-anchor" href="#思想封闭的迹象" aria-label="Permalink to &quot;思想封闭的迹象&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>思想封闭是指在任何情况下都无法超越你狭隘的视角去看待事物。</p><p>如果你的视角只能给那个情况投下负面的阴影，那就更糟了。</p><p>让我们以社交媒体的评论区为例。</p><p>有些人完全抓不住别人说话的重点，为了自己的利益去曲解它，然后留下与原始信息毫不相干的评论，这种情况有多常见？</p><p>就像当你读到一篇两极分化的政治帖子时，你感到被冒犯了，然后为了图方便而忽略了他们的视角，仅仅因为那与你的视角不一致。</p><p>你根本没有意识到，你的视角并不是绝对的真理，他们的也不是。而且，如果你努力去理解双方，你就会向着平和且富有创造性地解决问题的生活迈进。</p><p>人们没有意识到这些简单、无意识的行动背后的深意。你正在毁掉你的生活。怎么毁掉的？因为你没有在创造它。没有刻意的行动，唯一的出路就是走下坡路。</p><p>这不仅是思想封闭，也是一种分心。</p><p>人们无法将注意力集中在整体的结果上，而是对他们看到的东西挑挑拣拣，挑起争端，最后却一无所获。</p><p>这是寻求“速效解药”心态的另一种体现。</p><p>你在自己的脑海里“赢得了游戏”，收获了这样做的廉价多巴胺，并强化了那个坏习惯……你做得越多，就越难打破它。</p><p>宇宙是一首无尽的歌。Uni-verse（宇宙），即 One song（一首歌）。</p><p>歌曲是故事的象征。故事构成了游戏的结构。</p><p>所有的理解都是隐喻性的，大脑通过将符号串联成故事来理解世界。</p><p>那些不可避免的高潮、低谷、推、拉、阴和阳，构建了你对生活的理解。</p><p>其中大部分是<em>无法</em>用言语表达的。</p><p>语言很有用，但也极其局限。</p><p>这就是为什么游戏的结构能让我们的大脑变得有条理，并让我们进入心流状态。</p><p>本质上，思想封闭就是把你认为的故事当作真实情况，而不是去认清它实际的样子。</p><p>如果你想当然地认为别人的话可以无缝套入你脑海中正在上演的故事里，那你可要吃苦头了。</p><p>所以，让我们开始拓展你的思维。</p><p>这些都不会一蹴而就。</p><p>这是一个将无意识转变为有意识的过程，并且需要在几周、几个月甚至几年的时间里纠正你的行为。</p><p>让我们来看看几个暗示思想封闭的常见特征。</p><p>我把在日常生活中觉察到这一点的任务交给你自己。</p><p>当你开始觉察时，我鼓励你用我们在下一节讨论的策略慢慢纠正你的行动。</p><p>觉察带来进步。进步又会促进觉察。</p><h3 id="_1-假设与期望" tabindex="-1">1) 假设与期望 <a class="header-anchor" href="#_1-假设与期望" aria-label="Permalink to &quot;1) 假设与期望&quot;">​</a></h3><p>大多数人就是行走的“分心物”。</p><p>他们<em>本身</em>就是分心。他们的身份认同使他们偏离了真相。</p><p>你的现实是由你受到的后天条件反射（conditioning）决定的。</p><p>也就是说，你的身份认同容纳了你的视角。你的视角则容纳了你视为真理的信念、想法和经验。对于大多数人来说，这种视角或世界观，是与你的父母、文化和社会共有的。</p><p>这些都限制了你对可能性的认知。</p><p>如果你所知道的只有上学、工作和退休，你的行为也会随之跟进。</p><p>你的“程序设定”是一个由对世界根深蒂固的假设和期望组成的网络。</p><p>除非你能超越它们去拓展你的思维，否则你注定要在别人强加给你的限制中度过一生。</p><p>删掉上一句……应该是<em>你强加给自己的限制。</em></p><h3 id="_2-自私的视角" tabindex="-1">2) 自私的视角 <a class="header-anchor" href="#_2-自私的视角" aria-label="Permalink to &quot;2) 自私的视角&quot;">​</a></h3><p>在当下这一刻之外，每个人都在按照一个特定的目标行事。</p><p>这个目标可以是有意识的、潜意识的，或是无意识的。</p><p>大多数人是无意识的，他们的行为方式有利于自己的生存。而且，如果人类在概念层面上生存，他们的行为方式就会强化他们那些根深蒂固的信念、假设和期望。他们的行为方式旨在确认他们的自我形象。</p><p>在现实世界中，你是如何发现这一点的呢？</p><p>这并不难。</p><p>看看任何一篇政治帖子。</p><p>评论区里有多少人在争论对方错得有多离谱？有多少人愿意为自己的信仰去死？</p><p>共和党人会辩称他们的政治立场是最好的，因为他们是共和党人。</p><p>每一个自由职业者都会辩称他们的商业模式是最好的，因为他们是自由职业者。</p><p>每一个基督徒、穆斯林和无神论者都会辩称他们的信仰体系是最好的，因为他们就代表着那个信仰体系。</p><p>人们没有看到的是，这些人也同样是人。</p><p>他们经历了不同的文化、社会甚至商业条件的洗礼，这些过程将信念深深植入了他们的大脑。</p><p>在他们的精神、身体、财务和灵性环境中，这些信念最能服务于<em>他们的身份认同</em>。</p><p>如果你想要一个更全面的真相，你必须能够将你的意识转移到他们的脑海中。你必须证明自己是错的。</p><p>一切都是相对的，你必须明白，在某些国家，你的信仰会让你惹上杀身之祸。</p><p>他们根本不在乎你认为自己有多“对”。</p><p>而从宇宙的角度来看，每个人都是对的，每个人也都是错的。</p><h3 id="_3-字面解读" tabindex="-1"><strong>3) 字面解读</strong> <a class="header-anchor" href="#_3-字面解读" aria-label="Permalink to &quot;**3) 字面解读**&quot;">​</a></h3><p>当我说“消失6个月去好好提升自己”时，你是如何理解这句话的？</p><p>你觉得我真的是在叫你人间蒸发吗？</p><p>还是你觉得我是在为了写出更具冲击力的文字而使用隐喻？</p><p>不管你是不是基督徒，当你读《圣经》时，你真的认为诺亚在洪水中把<em>每一种</em>动物都各带了两只上那艘巨大的方舟吗？</p><p>也许他带了，也许没带，而这正是关键所在。</p><p>专注。</p><p>去理解这些文字所指向的<em>本质、教训或真理</em>。</p><p>还有，看在老天爷的份上，请千万别给我发信息挑我文章里的错别字了。</p><p>同样的道理。</p><p>专注。</p><h3 id="_4-抓不住重点" tabindex="-1">4) 抓不住重点 <a class="header-anchor" href="#_4-抓不住重点" aria-label="Permalink to &quot;4) 抓不住重点&quot;">​</a></h3><p>这和字面解读文字很相似。</p><p>网络喷子臭名昭著的原因就在于，他们会故意忽略任何帖子的重点。</p><p>他们死盯着那个与整体信息毫不相干的一点不放。</p><p>你不会从一首歌曲中单拎出一句歌词来单独播放，还指望它能说得通。</p><p>宇宙（The uni-verse，一首歌）也是如此。</p><p>不要因为死盯着故事的一部分不放，而错失了生命的意义，或它任何多维度的面向。</p><p>你生命中的低谷也是更宏大图景的一部分。</p><p>如果你看不到这一点，你的大脑就缺乏秩序，并最终会吞噬你。</p><h3 id="_5-逃避愿景" tabindex="-1">5) 逃避愿景 <a class="header-anchor" href="#_5-逃避愿景" aria-label="Permalink to &quot;5) 逃避愿景&quot;">​</a></h3><p>我们几乎在每一封信中都会讨论到为你的人生设定一个愿景。</p><p>这是我故意的。</p><p>你的愿景不可能一蹴而就。你需要不断的提醒。这样，你才能反思最近的经历，开始朝着更好的人生方向前进。</p><p>问题是，有些人完全回避了这个念头。</p><p>每个人内心深处都知道，自己有能力做得更多。</p><p>但是，实现那种潜能的路径并不清晰，而清晰的反面就是混乱。</p><p>为了掩盖这种混乱，他们用暂时的享乐来让自己分心。</p><p>即时满足现在感觉很好，但以后会带来痛苦。</p><p>为了你的目标而行动现在会带来痛苦，但以后会感觉很好。</p><p>拨动这个开关吧。</p><h2 id="敞开心扉——拉远视角的艺术" tabindex="-1">敞开心扉——拉远视角的艺术 <a class="header-anchor" href="#敞开心扉——拉远视角的艺术" aria-label="Permalink to &quot;敞开心扉——拉远视角的艺术&quot;">​</a></h2><blockquote><p>清空你的大脑。无形无相，像水一样。你把水倒进杯子，它就成了杯子的形状。——李小龙（Bruce Lee）</p></blockquote><p>大家都知道这句名言，但有多少人曾静下心来仔细品味，去质疑它，并让它用洞见填满自己的大脑呢？</p><p>大多数人读了它，以为自己在这种陈词滥调的理解游戏中“赢了”，从而获得一阵短暂的多巴胺快感，然后就把大脑封闭起来，不再去探究这句话背后的深意。</p><p>巅峰体验似乎是以下两种专注类型之一的结果：</p><ol><li>对眼前的事物保持超级专注，即<strong>做事（doing）</strong>。</li><li>什么都不抓取的极度开放的专注，即<strong>存在（being）</strong>。</li></ol><p>要么拥抱一切，要么归于虚无。</p><p>你要明白，这些都是意识的巅峰<em>状态</em>。如果你还有世俗的责任，这些状态即使不是不可能，也很难维持。</p><p>在这种意义上，当你的注意力集中在一个与你未来愿景相一致的目标层级上时，思想封闭反而是有用的。你与任务“合二为一”。你的大脑空无一念，因为没有什么可想的。你只需去做。</p><p>所以，在最极端的意义上，思想开放就是让你的大脑超越所有的形式、限制和分心物。与宇宙合二为一，而不是与任务合一。</p><p>在这种状态下，你不会执着于任何想法。你是层层叠叠的自我之下，那个沉默的观察者。</p><p>思想开放是分阶段的。</p><p>一个例子（排名不分先后）：</p><p><strong>第一阶段）</strong>你认为宗教是通往救赎的唯一途径。</p><p><strong>第二阶段）</strong>你认为宗教是精神控制。</p><p><strong>第三阶段）</strong>你认为如果从隐喻的视角来解读，宗教蕴含着深刻的真理。</p><p>在商业中，情况也是类似的：</p><p><strong>第一阶段）</strong>你认为自由职业是最好的商业模式。</p><p><strong>第二阶段）</strong>你认为大多数商业模式都是骗局。</p><p><strong>第三阶段）</strong>你认为所有的商业模式都包含一些真理，可以用来改进那个与你兴趣相符的模式。</p><p>哦，你瞧，<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">这有一门课程，恰好提供了我关于如何做到这一点的视角。</a></p><p>我们都认识一些人，他们采纳并认同上述每一种视角。</p><p>有些人比其他人更思想开放。</p><p>而那些思想开放的人，遭受的痛苦更少，获得的成功更多。</p><p>保持开放心态的好处显而易见：</p><p>更深层次的智慧、更高的创造力、更少的情绪化反应、圆满的人际关系、新颖的内容创意，以及能够巧妙应对像政治这样极易两极分化的领域。</p><p>所以，让我们深入探讨一些打开你思维的实用步骤。</p><p>并且，像往常一样，请在内心深处理解这不是一蹴而就的。在这里，试图寻找思维上的“速效药”是完全违背初衷的。</p><p>这是一项<em>终身</em>的实践。</p><p>意思是，如果你想获得开放思维带来的结果，它就必须成为你身份认同的一部分。</p><p>如果你不能每天都去践行，那你为什么要开始呢？</p><h3 id="_1-批判性思维-101" tabindex="-1">1) 批判性思维 101 <a class="header-anchor" href="#_1-批判性思维-101" aria-label="Permalink to &quot;1) 批判性思维 101&quot;">​</a></h3><p>将所有的想法、观念和观点都保留在“可能”的范畴内，直到它们经过直接经验的过滤。</p><p>你不需要在瞬间去证明某件事是对还是错。</p><p>你可以任由事情在你的脑海中沉淀发酵，而不必急于认同争论中的任何一方。</p><h3 id="_2-努力构建更宏观的身份认同" tabindex="-1">2) 努力构建更宏观的身份认同 <a class="header-anchor" href="#_2-努力构建更宏观的身份认同" aria-label="Permalink to &quot;2) 努力构建更宏观的身份认同&quot;">​</a></h3><p>你的身份认同承载着你的视角。</p><p>你的视角承载着你的信念。</p><p>你的信念影响着你的思想、情绪和行动。</p><p>因此，如果我们采纳一个比自身更宏大的身份认同，我们的思维也会随之打开。</p><p>这就是你发展自我（ego）的方式。</p><p>如果自我的运作是为了让我们认同的事物存活下来，而假设我们认同的是“全人类”，那么我们的行动就会致力于保护全人类。</p><p>我对此不是100%确定，但我相信某些人将自己认同为“上帝（God）”时，表达的就是这个意思。我们这里谈论的不是基督教概念中的上帝。我们谈论的是梵（Brahman）、绝对存在（the Absolute）、本源（Source）、无限（Infinity）、心智（Mind，非大脑）或宇宙（the Universe）。</p><p>可以这样想。</p><p>如果你在一个名为“雪鸟（Snowbirds）”的运动队，那你就会认同自己是一只“雪鸟”。这支队伍的精神形成了一个集体的自我，为你的比赛提供燃料。这种精神也会传递给那些认同该队伍的粉丝。</p><p>对一份公司工作、宗教或家庭的认同也是同样的道理。</p><p>要小心，要保持觉察，并在你的身份认同影响世界的过程中解决随时出现的问题。某些认同要么会封闭你的思维，要么会打开你的思维。</p><p><em><strong>请注意：我们是在心智或精神层面进行认同，而不是在肉体或智力层面。</strong></em></p><p>如果你想认同某种极度局限的东西，比如烤箱或阿帕奇武装直升机，请自便。或者，你可以退回到前面关于“故意抓错重点”的那一节。当然，除非重点是为了幽默，那还是挺有用的。</p><p>如果你就是宇宙——你也确实是——那么你那些琐碎的人类问题就会失去重量。而且，你可以从一个更好的制高点来看待政治、文化甚至全球层面的创造与毁灭。</p><p>将自己认同为宇宙有什么意义呢？</p><p>显然，不是为了高尚、地位或你脑子里冒出的任何其他自私企图，而是为了通过改进你的决策方式，从而让更多除了你之外的人受益。</p><p>也就是说，要看到超越你自身生存以外的东西。在从一个肤浅的享乐干扰转向另一个享乐干扰之前，三思而后行。</p><p>你的毕生事业将如何浸透这个世界的思想？</p><p>如果你热爱啤酒，你能开一家啤酒厂并将这份热情传递给你的顾客吗？</p><p>如果你热爱哲学，你能开始在网上写作并将你的见解传递给他人吗？</p><p>从宇宙的视角来看，这就是繁衍，或者说创造。你通过精神传递你的痴迷，因为人类已经超越了（并且包含了）肉体。</p><p>肉体当然很重要，但这仅仅是我们生命全部重要性中的一小部分。</p><p>这听起来很棒，但我们该如何发展自己来体现这一点呢？</p><h3 id="_3-收集意识" tabindex="-1">3) 收集意识 <a class="header-anchor" href="#_3-收集意识" aria-label="Permalink to &quot;3) 收集意识&quot;">​</a></h3><p>这需要几十年的时间，而且在这里我只能从个人经验出发来谈。</p><p>我并不是什么全能的大师，来准确告诉你该怎么做。</p><p>这只是我目前的理解水平，也是我正在努力的方向。</p><p>要收集意识，你需要理解构成一个更高层级身份认同的多种视角。</p><p>你需要<em>转移意识</em>，并寻求理解，而不是评判。</p><p>就像捕食者能够将意识转移到猎物身上，并预测它们的下一步行动。如果它们犯了错呢？那更好，随着时间的推移，你就是这样学会理解的。</p><p>如果动物能做到，你也能。营销人员、作家和创作者无时无刻不在这样做。</p><p>把你的意识转移到你的读者身上，他们会喜欢、互动并分享你的内容吗？还是你需要重写？</p><p>我在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 中从更实用的视角教授了这一点。</p><p>把你的意识转移到那个超车插队的司机身上，他们是赶时间吗？如果他们的母亲正在医院呢？还是说他们只应该关心你那为了舒适驾驶的自私需求？</p><p>在这里要关注大局，而不是细枝末节。当然，你不可能知道每个人对某个情况的具体想法。</p><p>但是，你可以理解他们的行动，留意其中的模式，并观察结果。我们想要理解的是那种<em>体验</em>，无论它能否用语言表达。</p><p>当然，你不可能仅仅通过试图理解某人的视角就能学会说他们的语言。我们在这里寻找的是超越单纯人类存在之上的<em>本质</em>。比如“力量”是如何在文化、社会、动物、科学以及宇宙中体现出来的。</p><p>当你把健美运动员当作一种身份认同来研究时，他们对食物的看法与普通人是不同的。</p><p>他们不需要费心去抵制垃圾食品。他们就是不吃，因为这样做能为他们的目标带来最优结果。</p><p>一个成功的商人不需要刻意去想在商业中保持连贯性。这就是他们的行事本能。</p><p>宇宙不需要考虑一颗恒星或行星的爆炸，因为在宏观格局中，其他事物会随之诞生。</p><p>这是一个我希望你自己去深思的问题。</p><p>从认同你自己最高版本的身份开始。这应该与你的愿景相一致。</p><p>去研究那些已经做成了你想做之事的人。</p><h3 id="_4-暂停与质疑" tabindex="-1">4) 暂停与质疑 <a class="header-anchor" href="#_4-暂停与质疑" aria-label="Permalink to &quot;4) 暂停与质疑&quot;">​</a></h3><p>一个挑战：</p><p>在任何领域，去研究与你的信念完全相反的观点。</p><p>如果你是纯素食主义者，去研究食肉主义者。</p><p>如果你是自由职业者，去研究创作者。</p><p>如果你是基督徒，去研究无神论者。</p><p>带着试图证明自己是错的心态去面对这些情况。</p><p>极少数能做到这一点的人，他们的进步将会一飞冲天。</p><p>这很难，而且你会体验到自我的抗拒。</p><p>你的大脑会与你所接触的那些信念展开一场假想的战斗。</p><p>你会感到受到威胁。面对一种信念时产生的战或逃反应。人类很有趣。那是你的自我概念在努力求存。</p><p>当你察觉到这种反应时，质疑它。</p><p>质疑就是你学习的方式。</p><p>在商业、宗教甚至健康领域，挑选一个你不认同的观点，然后思考以下问题。</p><p>当更多问题出现时，继续质疑。</p><ul><li>在这个情况中，有什么是我能学到的吗？</li><li>他们正在努力实现什么目标？</li><li>那与我的目标一致吗？如果不一致，有关系吗？</li><li>他们是在什么语境下说出这些话的？</li><li>他们所说的话中，<em>本质或教训</em>是什么？</li><li>我能将他们信念的某个方面融入到我自己的信念中吗？</li></ul><p>随着时间的推移，这些问题将会孕育出一些惊人的洞察力。</p><h3 id="_5-宏观思考-微观行动" tabindex="-1">5) 宏观思考，微观行动 <a class="header-anchor" href="#_5-宏观思考-微观行动" aria-label="Permalink to &quot;5) 宏观思考，微观行动&quot;">​</a></h3><p>你是一个视角的容器。</p><p>你的行动，无论你是否意识到，都会对世界产生影响。而在你肉体生命的时间尺度内，这些影响会累积得相当可观。</p><p>当你敞开心扉去容纳更宏观的视角时，你的行动也必须紧随其后。</p><p>着眼于大局，忘掉琐碎的细节，然后采取行动。</p><p>获得真知的<em>唯一</em>途径就是犯错。</p><p>知识是无限的，在相对的世界里，没有人绝对正确，只有相对正确。</p><p>你的工作就是犯错，纠正它们，并允许人类在漫长的岁月中不断进步，而不仅仅局限于你那微观的一生。</p><p>把格局放大。</p><p>请不要让你的旅程止步于这封信。</p><p>如果你想打开思维，你就必须改变你的心理习惯。</p><p>你必须设定一个寻求真理的意图——即使这不符合你的利益——并将保持开放的心态作为你生活中持续不断的实践。</p><p>你们每一个人的最高版本都是思想开放的。</p><p>试着拓展你的思维来体现那个身份认同。</p><p>让你的行动慢慢反映出这一点。</p><p>– Dan Koe</p><p><strong>本周回顾</strong></p><p>首期数字经济冲刺班（Digital Economics Sprint）将于2月中旬开始。在14天内，我们将打造你的“一人细分领域”，创作20多篇基础内容，并理清你品牌未来的发展方向。加入数字经济课程（Digital Economics）即可锁定名额。</p><p><a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">&gt;&gt; 报名参加数字经济课程</a></p><p>在《Modern Mastery》中，我发布了一项针对创意工作者（如设计师）的客户获取策略，它可以帮助你在获客的同时建立受众群。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">&gt;&gt; 读者仅需5美元即可加入</a></p><p>上周发布了2个YouTube视频。一个是关于《4小时工作日》（The 4-Hour Workday），另一个是关于如何给你的生活进行一次硬重启（hard reset）。</p><p><a href="https://youtube.com/c/DanKoeTalks" target="_blank" rel="noreferrer">&gt;&gt; 在这里观看视频</a></p><hr><p><a href="/en/letters/distraction-is-the-greatest-trap-of-the-21st-century">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',242))])}const T=r(c,[["render",d]]);export{q as __pageData,T as default};
